package com.wizzadrds.theworldremembers.knowledge;
import com.mojang.serialization.Codec; import com.mojang.serialization.codecs.RecordCodecBuilder; import net.minecraft.resources.Identifier; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.saveddata.SavedData; import net.minecraft.world.level.saveddata.SavedDataType; import java.util.*;
public final class ConversationManager extends SavedData{private final List<Conversation> conversations=new ArrayList<>();private static final Codec<Conversation>C=RecordCodecBuilder.create(i->i.group(Codec.STRING.xmap(UUID::fromString,UUID::toString).fieldOf("first").forGetter(Conversation::first),Codec.STRING.xmap(UUID::fromString,UUID::toString).fieldOf("second").forGetter(Conversation::second),Codec.LONG.fieldOf("tick").forGetter(Conversation::tick),Codec.STRING.fieldOf("topic").forGetter(Conversation::topic)).apply(i,Conversation::new));private static final SavedDataType<ConversationManager>TYPE=new SavedDataType<>(Identifier.fromNamespaceAndPath("the_world_remembers","conversations"),ConversationManager::new,C.listOf(),null);public static ConversationManager get(MinecraftServer s){ServerLevel l=s.getLevel(ServerLevel.OVERWORLD);return l==null?new ConversationManager():l.getDataStorage().computeIfAbsent(TYPE);}public void record(Conversation c){if(conversations.size()>=2048)conversations.remove(0);conversations.add(c);setDirty();}public List<Conversation>all(){return List.copyOf(conversations);}}
